"""Regression coverage for the behavior specified in SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_and_whitespace():
    assert parse_transcript_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        event("a", 1, True), event("b", -2, False), event("c", 3, None),
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", "\n", " \t\n", "# comment", " \t# not,a,record,at,all", "a,1,1"]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, True)]
    assert parse_transcript_log(lines[:-1]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# comment", " ", "ok,1,0", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        event("a", 1, True),
        event("b", 2, False),
        event("c", 3, True),
        event("a", 2, None),
        event("c", 0, False),
    ]
    assert dedupe_transcripts(events) == [events[4], events[3], events[1]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_missing_days():
    events = [
        event("outside-before", 0, True),
        event("a", 1, True),
        event("b", 1, True),
        event("c", 2, False),
        event("d", 3, None),
        event("e", 5, True),
        event("outside-after", 6, True),
    ]
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 5, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_pooled_rounded_rate_and_calendar_window():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 4, True), event("c", 6, False)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 2


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "low": [{"flagged": True}, {"flagged": None}],
        "a": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "low", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 3) == []
    assert top_flagged_groups({}, 3) == []


def test_flag_rate_by_group_sorted_keys_and_empty_groups():
    groups = {
        "z": [],
        "b": [{"flagged": None}],
        "a": [{"flagged": True}, {"flagged": None}],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.5, "b": 0.0, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3], 2),
     ([1, -1, 2, 3], 2), ([1, 0, 2, 3, 4], 3), ([1, 2, 3], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
